import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh, DoubleSide, SRGBColorSpace, ClampToEdgeWrapping } = THREE;

  const group = new Group();
  group.name = config.id || 'features-card-3-label';

  const specColors = config.intent?.visualSpec?.colors || config.colors || {};
  const ink = specColors.ink || '#16161d';
  const paper = specColors.paper || '#e8ecf2';

  const atlasX = 0;
  const atlasY = 0;
  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;

  const height = 0.45;
  const width = height * aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1,
    side: DoubleSide
  });
  material.colorNode = color(ink);

  const sprite = new Mesh(geometry, material);
  sprite.userData.isSprite = true;
  group.add(sprite);

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const item = textItems.find(t => t.role === 'headline') || textItems[0] || { text: 'Features 3', typography: { fontSize: 39 } };
  const labelText = ctx.fontAtlas.createText(String(item.text ?? 'Features 3'), {
    fontSize: item.typography?.fontSize ?? 39,
    color: paper,
    align: 'center'
  });
  labelText.position.z = 0.02;
  group.add(labelText);

  group.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  let loadedTexture = null;
  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (!group.parent) return;
      loadedTexture = tex;
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;

      const fullW = tex.image?.width || atlasW;
      const fullH = tex.image?.height || atlasH;
      tex.repeat.set(atlasW / fullW, atlasH / fullH);
      tex.offset.set(atlasX / fullW, 1 - (atlasY + atlasH) / fullH);

      material.map = texture(tex, uv());
      material.colorNode = null;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  group.scale.set(0.96, 0.96, 0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.6, ease: 'power2.out' }, 0);
  entranceTl.fromTo(material, { opacity: 0 }, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    entranceTl.kill();
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
